package com.bookstore.book.service;
import com.bookstore.book.dto.BookRequest; import com.bookstore.book.entity.Book; import com.bookstore.book.repository.BookRepository; import com.bookstore.category.repository.CategoryRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.List;
@Service public class BookService { private final BookRepository books; private final CategoryRepository categories; public BookService(BookRepository books, CategoryRepository categories){this.books=books;this.categories=categories;} public List<Book> all(){return books.findAll();} public Book byId(Long id){return books.findById(id).orElseThrow();} public Book create(BookRequest r){return save(new Book(),r);} public Book update(Long id,BookRequest r){return save(books.findById(id).orElseThrow(),r);} public void delete(Long id){books.deleteById(id);} private Book save(Book b,BookRequest r){b.setTitle(r.title());b.setAuthor(r.author());b.setPrice(r.price());b.setStock(r.stock());b.setCategory(r.categoryId()==null?null:categories.findById(r.categoryId()).orElseThrow());return books.save(b);} }

